// Broker-industry news — generated by /api/cron/broker-news.
//
// One doc per day, _id = `broker-news-YYYY-MM-DD`, exactly like dailyUpdate.
// A reader comparing brokers wants to know that the regulator fined one of
// them last week, and a directory that never changes reads as abandoned; this
// is the feed that answers both.
//
// It is deliberately a SEPARATE doc type from dailyUpdate rather than another
// array on it. The two have different schedules, different sources and
// different failure modes, and sharing a doc would mean a broker-news failure
// could roll back a market-news write committed minutes earlier.

export const brokerNewsSchema = {
  name: "brokerNews",
  title: "Broker News",
  type: "document",
  fields: [
    {
      name: "date",
      title: "ວັນທີ (YYYY-MM-DD, Asia/Vientiane)",
      type: "date",
      validation: (R: any) => R.required(),
    },
    {
      name: "items",
      title: "ຂ່າວ (ສະຫຼຸບເປັນລາວ)",
      type: "array",
      of: [
        {
          type: "object",
          fields: [
            { name: "id", title: "Slug ID", type: "string" },
            { name: "title", title: "ຫົວຂໍ້ (ລາວ)", type: "string" },
            { name: "summary", title: "ສະຫຼຸບ (ລາວ)", type: "text", rows: 3 },
            // regulation | expo | company | product — drives the chip on the
            // card. Free text rather than a list so a new kind of story does
            // not need a schema deploy before it can be published.
            { name: "category", title: "ປະເພດ", type: "string" },
            { name: "brokers", title: "ໂບຣກເກີທີ່ກ່ຽວຂ້ອງ", type: "array", of: [{ type: "string" }] },
            { name: "source", title: "Source URL", type: "url" },
            { name: "sourceName", title: "ຊື່ແຫຼ່ງ", type: "string" },
            { name: "sourceTitle", title: "ຫົວຂໍ້ຕົ້ນສະບັບ (EN)", type: "string" },
            { name: "imageUrl", title: "Image URL (og:image ຂອງຕົ້ນສະບັບ)", type: "url" },
            { name: "pubDate", title: "Publish Date", type: "string" },
          ],
          preview: { select: { title: "title", subtitle: "sourceName" } },
        },
      ],
    },
    {
      name: "rawNews",
      title: "Raw News (debug)",
      type: "array",
      of: [
        {
          type: "object",
          fields: [
            { name: "title", type: "string" },
            { name: "summary", type: "text" },
            { name: "link", type: "url" },
            { name: "pubDate", type: "string" },
            { name: "sourceName", type: "string" },
          ],
        },
      ],
      hidden: true,
    },
    { name: "createdAt", title: "Created At", type: "datetime", readOnly: true },
    { name: "lastError", title: "Last Error", type: "string", readOnly: true },
    // false = the raw feed was saved but the Lao summary never landed. The
    // retry schedule reads this; a true value makes the retry a no-op.
    { name: "pipelineComplete", title: "Pipeline Complete", type: "boolean", readOnly: true },
  ],
  orderings: [
    { title: "ວັນທີ ໃໝ່ສຸດ", name: "dateDesc", by: [{ field: "date", direction: "desc" }] },
  ],
  preview: {
    select: { date: "date", items: "items" },
    prepare: ({ date, items }: any) => ({
      title: date ?? "(no date)",
      subtitle: `${items?.length ?? 0} ຂ່າວ`,
    }),
  },
}
